import { AnimatePresence, motion } from 'motion/react';
import { useId, type ReactNode } from 'react';
import { IconChevronDown } from '../../../icons/chevron-down';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { useReducedMotion } from '../../../primitives/use-reduced-motion';
import { springs } from '../../../tokens/tokens';
import './expandable-card.css';

export interface ExpandableCardProps {
  title: string;
  /** Always visible under the title. */
  summary?: ReactNode;
  /** Revealed when the card opens. */
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Heading level of the title, to fit the page outline. */
  headingLevel?: 2 | 3 | 4;
  className?: string;
}

/**
 * A card that opens into its details in place. The card's size animates with a spring
 * (motion's layout animation), the heading stays where it is, and focus never moves:
 * the toggle you pressed is still focused when the card has opened.
 */
export function ExpandableCard({
  title,
  summary,
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  headingLevel = 3,
  className,
}: ExpandableCardProps) {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const reduced = useReducedMotion();
  const id = useId();
  const Heading = `h${headingLevel}` as const;
  const transition = reduced ? { duration: 0 } : { type: 'spring' as const, ...springs.mooring };

  return (
    <motion.article
      layout
      transition={transition}
      className={['atl-expand', className].filter(Boolean).join(' ')}
      data-open={open || undefined}
      style={{ borderRadius: 12 }}
    >
      <motion.div layout="position" transition={transition} className="atl-expand__head">
        <Heading className="atl-expand__title">
          <button
            type="button"
            className="atl-expand__toggle"
            aria-expanded={open}
            aria-controls={`${id}-details`}
            onClick={() => setOpen((o) => !o)}
          >
            {title}
            <IconChevronDown className="atl-expand__chevron" size={18} />
          </button>
        </Heading>
        {summary ? <div className="atl-expand__summary">{summary}</div> : null}
      </motion.div>
      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            key="details"
            id={`${id}-details`}
            className="atl-expand__details"
            initial={{ opacity: 0, y: -6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: reduced ? 0 : 0.12 } }}
            transition={reduced ? { duration: 0 } : { duration: 0.24, delay: 0.06 }}
          >
            {children}
          </motion.div>
        ) : null}
      </AnimatePresence>
    </motion.article>
  );
}

@layer atlas.components {
  .atl-expand {
    display: grid;
    gap: var(--space-s);
    padding: var(--space-m);
    overflow: hidden;
    background: var(--shoal);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 50%, transparent);
  }

  .atl-expand[data-open] {
    background: color-mix(in oklch, var(--shoal), var(--reef) 40%);
  }

  .atl-expand__head {
    display: grid;
    gap: var(--space-2xs);
  }

  .atl-expand__title {
    font-size: var(--step-1);
  }

  .atl-expand__toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-s);
    width: 100%;
    min-height: var(--target-comfort);
    padding: 0;
    border: 0;
    border-radius: var(--radius-control);
    background: none;
    color: var(--ink);
    font: inherit;
    font-weight: 650;
    text-align: left;
  }

  .atl-expand__chevron {
    flex: none;
    color: var(--ink-soft);
    transition: rotate var(--dur-step) var(--ease-anchor);
  }

  .atl-expand__toggle[aria-expanded='true'] .atl-expand__chevron {
    rotate: 180deg;
  }

  .atl-expand__summary {
    color: var(--ink-soft);
  }

  .atl-expand__details {
    font-family: var(--font-prose);
    line-height: var(--leading-prose);
  }
}
